<?php
declare(strict_types=1);
/**
 * Invoices & Billing — tax invoices generated by addon purchases.
 *
 * Payment receipts for captured orders live on the order itself
 * (`/invoice.php?order_id=…`); this page is about what the merchant owes or has
 * been billed for, which is a different document and a different table.
 */
require_once __DIR__.'/includes/merchant.php';
require_once __DIR__.'/includes/auth.php';
require_once __DIR__.'/includes/pager.php';
$merchant = require_login();
$pageTitle = 'Invoices';
$pdo = db();
$id = (int)$merchant['id'];

/* Paged. The counters and the two money totals are computed over the whole
   table, not the visible page, otherwise "Invoices: 3" would change as you
   paged and the billing totals would be quietly wrong. */
$totRow = $pdo->prepare("SELECT COUNT(*) n,
                                COALESCE(SUM(CASE WHEN status='paid' THEN amount+tax_amount ELSE 0 END),0) paid,
                                COALESCE(SUM(CASE WHEN status<>'paid' THEN amount+tax_amount ELSE 0 END),0) unpaid
                         FROM invoices WHERE merchant_id=?");
$totRow->execute([$id]);
$agg = $totRow->fetch();
$invoiceTotal = (int)$agg['n'];
$invoicePage = tg_paginate($invoiceTotal, 25);
$totals = ['paid' => (float)$agg['paid'], 'unpaid' => (float)$agg['unpaid']];

$q = $pdo->prepare('SELECT * FROM invoices WHERE merchant_id=? ORDER BY issued_at DESC, id DESC LIMIT '
    .$invoicePage['perPage'].' OFFSET '.$invoicePage['offset']);
$q->execute([$id]);
$invoices = $q->fetchAll();

require __DIR__.'/includes/dashboard-header.php';
?>

<div class="page-title-row" style="margin-bottom:20px">
  <h1 style="font-size:22px;font-weight:700;letter-spacing:-.5px;margin:0">Invoices &amp; Billing History</h1>
  <p style="font-size:13px;color:var(--color-ink-mute);margin:4px 0 0">Billing records for addons and services, separate from customer payment receipts.</p>
</div>

<?php if ($invoiceTotal > 0): ?>
  <div class="stat-grid" style="margin-bottom:20px">
    <div class="stat-card">
      <div class="stat-card-top"><div class="stat-card-label">Invoices</div><div class="stat-card-icon blue"><?=icon('file-text', 18)?></div></div>
      <div class="stat-card-value tnum"><?=number_format($invoiceTotal)?></div>
    </div>
    <div class="stat-card">
      <div class="stat-card-top"><div class="stat-card-label">Settled</div><div class="stat-card-icon green"><?=icon('check-circle', 18)?></div></div>
      <div class="stat-card-value tnum" style="color:#10b981">₹<?=number_format($totals['paid'], 2)?></div>
    </div>
    <div class="stat-card">
      <div class="stat-card-top"><div class="stat-card-label">Outstanding</div><div class="stat-card-icon orange"><?=icon('clock', 18)?></div></div>
      <div class="stat-card-value tnum">₹<?=number_format($totals['unpaid'], 2)?></div>
    </div>
  </div>
<?php endif ?>

<div class="card" style="padding:0;overflow:hidden">
  <div class="table-responsive">
    <table class="table">
      <thead><tr><th>Invoice</th><th>Description</th><th>Issued</th><th>Amount</th><th>Tax</th><th>Total</th><th>Status</th><th></th></tr></thead>
      <tbody>
      <?php if (!$invoices): ?>
        <tr><td colspan="8">
          <div class="empty-state">
            <div class="empty-state-icon"><?=icon('file-text', 22)?></div>
            <div class="empty-state-title">No Invoices Yet</div>
            <div class="empty-state-sub">When you purchase an addon or power-up, your invoices and receipts appear here.</div>
            <a class="btn btn-secondary btn-sm" href="/addons.php" style="margin-top:14px">Browse Addons Marketplace</a>
          </div>
        </td></tr>
      <?php endif ?>
      <?php foreach ($invoices as $inv): ?>
        <tr>
          <td><code style="font-size:12px;font-weight:600"><?=h((string)$inv['invoice_no'])?></code></td>
          <td><?=h((string)$inv['description'])?></td>
          <td style="white-space:nowrap"><?=h(date('d M Y', strtotime((string)$inv['issued_at'])))?></td>
          <td class="tnum" style="font-weight:600">₹<?=number_format((float)$inv['amount'], 2)?></td>
          <td class="tnum">₹<?=number_format((float)$inv['tax_amount'], 2)?></td>
          <td class="tnum" style="font-weight:600">₹<?=number_format((float)$inv['amount'] + (float)$inv['tax_amount'], 2)?></td>
          <td><span class="status-badge status-<?=($inv['status'] ?? '') === 'paid' ? 'success' : 'pending'?>"><?=h(ucfirst((string)($inv['status'] ?? 'paid')))?></span></td>
          <td><a class="btn btn-secondary btn-sm" href="/billing-invoice.php?id=<?=(int)$inv['id']?>">View</a></td>
        </tr>
      <?php endforeach ?>
      </tbody>
    </table>
  </div>
  <?=tg_pager($invoicePage)?>
</div>

<div class="callout callout-info" style="margin-top:20px">
  <?=icon('alert-circle', 16)?>
  <span>Looking for a receipt for a customer payment? Those live on each order —
    open <a href="/transactions.php" style="font-weight:600">Transactions</a> and choose “Receipt”.</span>
</div>

<?php require __DIR__.'/includes/dashboard-footer.php'; ?>
